/// <reference types="vite/client" />
import "./guide-style.css";
import { parseAdvice, parsePaste, renderCharacter, renderGuide, renderNext, type GuideOut } from "./guide-view";

// guide.json is generated by `pnpm guide ideal`; falls back to the sample fixture.
const real = Object.values(import.meta.glob("./data/guide.json", { eager: true, import: "default" }))[0] as GuideOut | undefined;
const sample = Object.values(import.meta.glob("./data/guide.sample.json", { eager: true, import: "default" }))[0] as GuideOut;
document.getElementById("ideal")!.innerHTML =
  (real ? "" : `<p class="gl-banner">sample data: run <code>pnpm guide ideal</code> to generate the real guide</p>`) + renderGuide(real ?? sample);

// the player's own character: what the poorchlight button copied, kept in this browser only
const KEY = "tli-lens:paste", PRICES = "tli-lens:prices";
const box = document.getElementById("paste-text") as HTMLTextAreaElement, out = document.getElementById("mine-out")!;
/** the prices you typed (item name -> FE), kept in this browser */
const mine = (): Record<string, number> => { try { return JSON.parse(localStorage.getItem(PRICES) ?? "{}"); } catch { return {}; } };
let advice: GuideOut | undefined;
const redrawNext = () => { const el = document.getElementById("gl-next"); if (advice?.next && el) el.outerHTML = renderNext(advice.next, advice.prices ?? {}, mine()); };
out.addEventListener("change", (e) => {
  const t = e.target as HTMLInputElement, name = t.dataset?.name;
  if (name === undefined) return;
  const m = mine(), v = Number(t.value);
  if (t.value.trim() === "" || !(v >= 0)) delete m[name]; else m[name] = v;
  localStorage.setItem(PRICES, JSON.stringify(m));
  redrawNext();
});
out.addEventListener("click", (e) => {
  const act = (e.target as HTMLElement).dataset?.act;
  if (act === "reset") { localStorage.removeItem(PRICES); redrawNext(); }
  if (act === "download") {
    const a = Object.assign(document.createElement("a"), { download: "prices.json", href: URL.createObjectURL(new Blob([JSON.stringify(mine(), null, 1) + "\n"], { type: "application/json" })) });
    a.click(); URL.revokeObjectURL(a.href);
  }
});
function show(text: string): void {
  if (!text.trim()) { out.innerHTML = ""; return; }
  try {
    const p = parsePaste(text);
    advice = p.kind === "advice" ? p.guide : undefined;
    out.innerHTML = p.kind === "advice" ? renderGuide(p.guide, mine())
      : renderCharacter(p.character) + `<p class="gl-banner">This is the raw export: it shows your gear, not what to change. Recommendations come from the guide engine, which runs on your PC
        (it needs dps-debug): the poorchlight button runs it and copies the result, or run <code>pnpm guide advise &lt;export.json&gt;</code> in tli-lens. Paste that result here.</p>`;
    localStorage.setItem(KEY, text);
    document.getElementById("paste")!.removeAttribute("open");
  } catch (e) { out.innerHTML = `<p class="warn"></p>`; out.firstElementChild!.textContent = (e as Error).message; }
}
document.getElementById("paste-go")!.addEventListener("click", () => show(box.value));
document.getElementById("paste-clear")!.addEventListener("click", () => { localStorage.removeItem(KEY); box.value = ""; out.innerHTML = ""; document.getElementById("paste")!.setAttribute("open", ""); });
// advice.json is written by `pnpm guide auto` (your plan from the live game, no pasting): shown first; a paste still replaces it until reload
const auto = Object.values(import.meta.glob("./data/advice.json", { eager: true, import: "default" }))[0] as GuideOut | undefined;
const kept = localStorage.getItem(KEY);
if (auto) {
  try {
    advice = parseAdvice(JSON.stringify(auto));
    out.innerHTML = `<p class="gl-banner">Your plan, read from your game (prices ${advice.etor.fetchedAt.slice(0, 16).replace("T", " ")} UTC)</p>` + renderGuide(advice, mine());
    document.getElementById("paste")!.removeAttribute("open");
    // your plan is the page: the ideal path stays as a folded reference below it
    const ideal = document.getElementById("ideal")!;
    ideal.innerHTML = `<details class="gl-ref"><summary>Ideal path from level 60 (reference only, not your character)</summary>${ideal.innerHTML}</details>`;
  } catch (e) { out.innerHTML = `<p class="warn"></p>`; out.firstElementChild!.textContent = (e as Error).message; }
} else if (kept) { box.value = kept; show(kept); }
